// Cloud Rain: a cloudscape drawn with characters, with characters falling over it like rain.
// Framework-free, no dependencies. This file is the single source for the hosted page, the
// downloadable HTML and the React / plain JS exports.
//
//   import { mount } from './cloud-rain.js'
//   const shader = mount(canvas, { effect: 'evening', cell: 8 })
//   shader.update({ speed: 12 })   // change settings live
//   shader.destroy()               // stop and release everything
//
// The canvas is drawn at whatever size CSS gives it and follows it when it changes.

export const GLYPHS = { digits: '0123456789', binary: '01', hex: '0123456789ABCDEF', symbols: '+-=*/<>#%&' };

export const LIMITS = {       // [min, max, default]; out-of-range values are clamped
  cell: [4, 16, 4],           // cell width, CSS px (smaller = closer to the picture)
  speed: [1, 30, 6],          // average fall speed, cells per second
  density: [0, 1, .8],        // share of columns that carry a rain drop
  trail: [2, 40, 18],         // average trail length, cells
  contrast: [.6, 1.8, 1.14],  // >1 restores the punch lost by averaging the picture's halftone dots
};

// Colour effects are fixed presets. Each regrades the picture in two parts: sky, as a gradient
// from the top of the frame to the horizon, and cloud, as shadow -> mid -> highlight by
// brightness. `ink` tints the characters that sit on bright cells.
export const EFFECTS = {
  original: null,
  evening: { sky: [[44, 26, 104], [255, 120, 70]], cloud: [[46, 26, 84], [176, 72, 128], [255, 212, 152]], ink: [150, 50, 120] },
  autumn: { sky: [[20, 70, 90], [92, 146, 142]], cloud: [[84, 36, 18], [214, 124, 54], [255, 238, 204]], ink: [150, 70, 20] },
  candy: { sky: [[255, 116, 190], [116, 188, 255]], cloud: [[146, 116, 230], [255, 186, 224], [255, 255, 255]], ink: [226, 96, 170] },
  midnight: { sky: [[4, 8, 40], [30, 46, 112]], cloud: [[10, 14, 44], [62, 78, 146], [206, 216, 255]], ink: [40, 60, 170] },
};

// The default picture, downsampled and embedded so this file works alone, including from
// file:// (a separate image file would taint the canvas there). Pass `image` to use your own;
// an image from another site must be served with CORS headers.
// ponytail: the default is 640px wide, soft above ~4K; pass a larger `image` if that matters.
const DEFAULT_IMAGE = 'data:image/jpeg;base64,';

const STEP = 20;              // posterise step per colour channel; the ordered dither hides the banding
const FADE_MS = 1100;         // how long a colour effect change takes to roll down the screen
const BAYER = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5].map(v => (v + .5) / 16);
const bayer = (x, y) => BAYER[(y & 3) << 2 | (x & 3)];
const mix = (a, b, t) => a + (b - a) * t;

function grade(r, g, b, v, fx) { // v: 0 at the top of the frame, 1 at the bottom
  if (!fx) return [r, g, b];
  const sky = Math.min(1, Math.max(0, (b - Math.max(r, g)) / 160)); // how blue-saturated, i.e. how much open sky
  // The picture's clouds are mostly bright, so stretch brightness to use the whole cloud ramp.
  const l = Math.min(1, Math.max(0, ((r * .3 + g * .59 + b * .11) / 255 - .25) / .7));
  const lo = fx.cloud[l < .5 ? 0 : 1], hi = fx.cloud[l < .5 ? 1 : 2], t = l < .5 ? l * 2 : l * 2 - 1;
  const h = Math.min(1, v * 1.4); // open sky sits in the upper part of the frame; reach the horizon colour sooner
  return [0, 1, 2].map(i => mix(mix(lo[i], hi[i], t), mix(fx.sky[0][i], fx.sky[1][i], h), sky));
}

// Merge settings into P, ignoring anything invalid. Returns true if something changed.
function setParams(P, o) {
  let changed = false;
  for (const k in LIMITS) {
    const v = Number(o?.[k]);
    if (o?.[k] == null || o[k] === '' || !Number.isFinite(v)) continue;
    const c = Math.min(LIMITS[k][1], Math.max(LIMITS[k][0], v));
    if (c !== P[k]) { P[k] = c; changed = true; }
  }
  for (const [k, set] of [['glyphs', GLYPHS], ['effect', EFFECTS]])
    if (Object.hasOwn(set, o?.[k]) && o[k] !== P[k]) { P[k] = o[k]; changed = true; }
  return changed;
}
{
  const p = { cell: 6, glyphs: 'digits' };
  console.assert(!setParams(p, { cell: 'x', glyphs: 'nope' }) && setParams(p, { cell: 99 }) && p.cell === 16, 'setParams broken');
}

export function mount(canvas, options = {}) {
  const ctx = canvas.getContext('2d');
  const img = new Image();
  const still = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const P = { glyphs: 'digits', effect: 'original' };
  for (const k in LIMITS) P[k] = LIMITS[k][2];
  setParams(P, options);

  // px: the picture sampled once per cell. C/S/atlas: colour, ink set and glyph sprites for the
  // current look. THR: when each cell flips during a change. fade: the previous look, while one runs.
  let cw, ch, cols, rows, px, C, S, atlas, G, K, THR, drops, N, fade = null, live = false, raf = 0, dead = false;

  const quant = (v, b) => Math.max(0, Math.min(255, Math.round(((v - 128) * P.contrast + 131 + (b - .5) * STEP) / STEP) * STEP));
  // Speed and trail vary +-50% around their setting so columns don't fall in lockstep.
  const rainOf = () => ({ v: P.speed * (.5 + Math.random()), len: Math.max(1, P.trail * (.5 + Math.random())), on: Math.random() < P.density });
  const newDrop = () => ({ y: -Math.random() * rows * .35, ...rainOf() });

  function setup() {
    const dpr = window.devicePixelRatio || 1;
    canvas.width = Math.max(1, Math.round(canvas.clientWidth * dpr));
    canvas.height = Math.max(1, Math.round(canvas.clientHeight * dpr));
    N = GLYPHS[P.glyphs].length;
    cw = Math.round(P.cell * dpr); ch = Math.round(P.cell * 1.5 * dpr);
    cols = Math.ceil(canvas.width / cw); rows = Math.ceil(canvas.height / ch);
    const n = cols * rows;
    px = sample(cols, rows, cw / ch);
    G = Uint8Array.from({ length: n }, () => Math.random() * N); // glyph per cell
    K = new Uint8Array(n).fill(255);                       // last drawn (fade side, level, glyph), to skip unchanged cells
    // A change rolls down the screen, broken up by the dither pattern and a little per column so it reads as rain.
    const jitter = Float32Array.from({ length: cols }, Math.random);
    THR = Float32Array.from({ length: n }, (_, i) => { const x = i % cols, y = i / cols | 0; return y / rows * .6 + bayer(x, y) * .25 + jitter[x] * .15; });
    // Keep rain where it was across a re-setup when the grid width is unchanged; otherwise scatter it down the screen.
    drops = Array.from({ length: cols }, (_, x) => drops?.length === cols ? drops[x] : { ...newDrop(), y: (Math.random() * 1.4 - .2) * rows });
    fade = null;
    paint();
    live = true;
  }

  // The picture cover-fitted to a w x h grid whose cells have the given aspect, as RGBA bytes.
  function sample(w, h, aspect) {
    const s = document.createElement('canvas'); s.width = w; s.height = h;
    const sc = s.getContext('2d'), k = Math.max(w / img.width, h / aspect / img.height);
    const sw = w / k, sh = h / aspect / k;
    sc.drawImage(img, (img.width - sw) / 2, (img.height - sh) / 2, sw, sh, 0, 0, w, h);
    return sc.getImageData(0, 0, w, h).data;
  }

  // One cell's final colour: graded by the effect, then ordered-dither + posterise for the pixelated look.
  function cellRGB(data, i, x, y, h, fx) {
    const b = bayer(x, y), c = grade(data[i * 4], data[i * 4 + 1], data[i * 4 + 2], y / h, fx);
    return [quant(c[0], b), quant(c[1], b), quant(c[2], b)];
  }

  // Colours and glyph sprites for the current effect, contrast and character set.
  function paint() {
    const fx = EFFECTS[P.effect], n = cols * rows;
    C = new Array(n); S = new Uint8Array(n);               // cell colour, cell ink set
    for (let i = 0; i < n; i++) {
      const [r, g, b] = cellRGB(px, i, i % cols, i / cols | 0, rows, fx);
      C[i] = `rgb(${r},${g},${b})`;
      S[i] = r * .3 + g * .59 + b * .11 > 150 ? 1 : 0;
    }
    // Glyph sprites, transparent background. Two inks (white for dark/mid cells, the effect's tint
    // for bright cells), three rain levels each: still (texture), trail, head.
    const glyphs = GLYPHS[P.glyphs], tint = fx?.ink ?? [20, 50, 215];
    const INK = [
      ['rgba(255,255,255,.17)', 'rgba(255,255,255,.62)', '#ffffff'],
      [`rgba(${tint},.18)`, `rgba(${tint},.62)`, `rgb(${tint})`],
    ];
    atlas = document.createElement('canvas');               // a new one, so a running fade keeps the old sprites
    atlas.width = cw * N; atlas.height = ch * 6;
    const actx = atlas.getContext('2d');
    actx.font = `bold ${ch}px ui-monospace, Consolas, Menlo, monospace`;
    actx.textAlign = 'center'; actx.textBaseline = 'middle';
    for (let set = 0; set < 2; set++) for (let lv = 0; lv < 3; lv++) {
      actx.fillStyle = INK[set][lv];
      for (let d = 0; d < N; d++) actx.fillText(glyphs[d], d * cw + cw / 2, (set * 3 + lv) * ch + ch / 2 + 1);
    }
  }

  function frame(dt) {
    for (let x = 0; x < cols; x++) {
      const d = drops[x];
      d.y += d.v * dt;
      if (d.y - d.len > rows) drops[x] = newDrop();
    }
    for (let n = cols * rows * .003; n > 0; n--) G[Math.random() * G.length | 0] = Math.random() * N;

    // Progress of a running effect change, eased; cells whose THR is below it show the new look.
    let p = 1;
    if (fade) { p = (performance.now() - fade.t0) / FADE_MS; if (p >= 1) { fade = null; p = 1; } else p = p * p * (3 - 2 * p); }

    for (let x = 0; x < cols; x++) {
      const head = Math.floor(drops[x].y), len = drops[x].len, on = drops[x].on;
      for (let y = 0; y < rows; y++) {
        const i = y * cols + x, k = head - y;
        const lv = !on ? 0 : k === 0 ? 2 : k > 0 && k < len && (1 - k / len) * 2 > bayer(x, y) ? 1 : 0; // solid streak, dithered only at the tail end
        if (lv === 2) G[i] = Math.random() * N;
        const nw = !fade || THR[i] < p, key = (lv * N + G[i]) << 1 | nw;
        if (K[i] === key) continue;
        K[i] = key;
        const L = nw ? { C, S, atlas } : fade;
        ctx.fillStyle = L.C[i]; ctx.fillRect(x * cw, y * ch, cw, ch);
        ctx.drawImage(L.atlas, G[i] * cw, (L.S[i] * 3 + lv) * ch, cw, ch, x * cw, y * ch, cw, ch);
      }
    }
  }

  // Follow the canvas's CSS size. The observer also fires once on observe, which is harmless.
  const sized = new ResizeObserver(() => {
    const dpr = window.devicePixelRatio || 1;
    if (!live || (canvas.width === Math.round(canvas.clientWidth * dpr) && canvas.height === Math.round(canvas.clientHeight * dpr))) return;
    setup(); if (still) frame(0);
  });

  const ready = new Promise((resolve, reject) => {
    img.onload = () => {
      if (dead) return;
      setup();
      sized.observe(canvas);
      if (still) frame(0);                                  // reduced motion: one still frame, redrawn on change
      else {
        let last = performance.now();
        raf = requestAnimationFrame(function loop(now) {
          frame(Math.min(.05, (now - last) / 1000)); last = now;
          raf = requestAnimationFrame(loop);
        });
      }
      resolve();
    };
    img.onerror = () => reject(new Error('cloud-rain: the image could not be loaded'));
  });
  const src = options.image || DEFAULT_IMAGE;
  if (!src.startsWith('data:')) img.crossOrigin = 'anonymous';
  img.src = src;

  return {
    ready,                                                  // resolves once the first frame is drawn
    // Apply new settings: rain-only changes retune the drops in place, a new effect fades in,
    // contrast repaints, and a new cell size or character set rebuilds the grid.
    update(o) {
      const before = { ...P };
      if (!setParams(P, o) || !live) return;
      if (P.cell !== before.cell || P.glyphs !== before.glyphs) setup();
      else if (P.effect !== before.effect) {
        if (!still) fade = { C, S, atlas, t0: performance.now() };
        paint(); if (still) K.fill(255);
      } else if (P.contrast !== before.contrast) { paint(); K.fill(255); }
      if (P.speed !== before.speed || P.trail !== before.trail || P.density !== before.density) for (const d of drops) Object.assign(d, rainOf());
      if (still) frame(0);
    },
    // A small still of every effect as a data URL, rendered with the same grade and dither as
    // the animation, so previews can never drift from the real look. Call after `ready`.
    thumbs(w = 64, h = 40) {
      const data = sample(w, h, 1), out = {};
      const t = document.createElement('canvas'); t.width = w; t.height = h;
      const tc = t.getContext('2d'), im = tc.createImageData(w, h);
      for (const name in EFFECTS) {
        for (let i = 0; i < w * h; i++) { im.data.set(cellRGB(data, i, i % w, i / w | 0, h, EFFECTS[name]), i * 4); im.data[i * 4 + 3] = 255; }
        tc.putImageData(im, 0, 0);
        out[name] = t.toDataURL();
      }
      return out;
    },
    destroy() { dead = true; live = false; cancelAnimationFrame(raf); sized.disconnect(); },
  };
}
